import { useState, useRef, useEffect, Fragment } from "react";
// ── SUPABASE CONFIG ─────────────────────────────────────────────────────────── v6
const SUPA_URL = "https://kpaddzigzqbnkfzprlwl.supabase.co";
const SUPA_KEY = "sb_publishable_RZaBuoZXGvPNTZaqGjHMlQ_kMH_dTVG";

let __dbErrShown=false;
const __saveQueues={};
let __deleteQueue=Promise.resolve();
// Rastreia salvamentos locais recentes (table::id -> timestamp) para proteger contra
// eventos de tempo real chegando fora de ordem (ex: INSERT antigo chegando depois de um
// UPDATE mais novo) e sobrescrevendo uma edição recém-feita com dados antigos.
const __recentLocalSaves={};
const RECENT_SAVE_WINDOW_MS=10000;
const db = {
  async get(table) {
    try {
      let allRows = [];
      let from = 0;
      const step = 1000;
      let guard = 0; // proteção contra loop infinito
      while(guard++ < 500) {
        const res = await fetch(`${SUPA_URL}/rest/v1/${table}?select=*&order=id.asc&limit=${step}&offset=${from}`, {
          cache: "no-store",
          headers: {"apikey": SUPA_KEY, "Authorization": `Bearer ${SUPA_KEY}`, "Cache-Control": "no-cache"}
        });
        if(!res.ok){ const t=await res.text(); console.error("DB get error:",table,res.status,t); if(!__dbErrShown&&res.status!==404){__dbErrShown=true;alert("Erro ao LER ("+table+"): "+res.status+" — "+t.slice(0,200));} break; }
        const rows = await res.json();
        if(!Array.isArray(rows) || rows.length===0) break; // página vazia = acabou, garantido, sem depender de headers
        allRows = allRows.concat(rows);
        from += rows.length;
      }
      return allRows.map(r => r.data);
    } catch(e) { console.error("DB get error:", e); return []; }
  },
  save(table, id, data) {
    __recentLocalSaves[table+"::"+id]=Date.now();
    // Enfileira gravações do MESMO registro (mesma tabela+id) para que sempre sejam
    // enviadas ao servidor em ordem, evitando que uma grava mais antiga (ex: criação)
    // chegue depois de uma mais nova (ex: edição do serviço) e sobrescreva o resultado.
    const key = table+"::"+id;
    const prev = __saveQueues[key] || Promise.resolve();
    const next = prev.then(async () => {
      try {
        const res = await fetch(`${SUPA_URL}/rest/v1/${table}`, {
          method: "POST",
          cache: "no-store",
          headers: {"apikey": SUPA_KEY, "Authorization": `Bearer ${SUPA_KEY}`, "Content-Type": "application/json", "Prefer": "resolution=merge-duplicates,return=representation"},
          body: JSON.stringify({id, data})
        });
        const text = await res.text();
        if(!res.ok){ console.error("DB save error:",table,res.status,text); alert("❌ Erro ao SALVAR ("+table+"): "+res.status+" — "+text.slice(0,250)); return {ok:false,status:res.status,body:text}; }
        let parsed=null; try{parsed=JSON.parse(text);}catch(e){}
        return {ok:true,status:res.status,body:parsed};
      } catch(e) { console.error("DB save error:", e); alert("Erro de conexão ao salvar: "+e.message); return {ok:false,error:e.message}; }
    });
    __saveQueues[key] = next;
    return next;
  },
  delete(table, id) {
    const prev = __deleteQueue || Promise.resolve();
    const next = prev.then(async () => {
      try {
        await fetch(`${SUPA_URL}/rest/v1/${table}?id=eq.${id}`, {
          method: "DELETE",
          headers: {"apikey": SUPA_KEY, "Authorization": `Bearer ${SUPA_KEY}`}
        });
      } catch(e) { console.error("DB delete error:", e); }
    }).catch(()=>{});
    __deleteQueue = next;
    return next;
  },
  // Salva várias linhas de uma vez (usado nas importações de Excel). Envia em lotes pequenos e em
  // sequência (não tudo de uma vez) pra não sobrecarregar o banco quando a planilha tem centenas/milhares
  // de linhas — evita que parte das linhas "suma" silenciosamente por excesso de requisições simultâneas.
  async saveBatch(table, rows, chunkSize=150) {
    if(!rows||rows.length===0)return {ok:true,okCount:0,failedCount:0};
    let okCount=0; const falhas=[];
    for(let i=0;i<rows.length;i+=chunkSize){
      const chunk=rows.slice(i,i+chunkSize).map(d=>({id:d.id,data:d}));
      const chunkPromise=(async()=>{
        try{
          const res=await fetch(`${SUPA_URL}/rest/v1/${table}`,{
            method:"POST", cache:"no-store",
            headers:{"apikey":SUPA_KEY,"Authorization":`Bearer ${SUPA_KEY}`,"Content-Type":"application/json","Prefer":"resolution=merge-duplicates,return=minimal"},
            body:JSON.stringify(chunk)
          });
          if(!res.ok){ const t=await res.text(); console.error("DB saveBatch error:",table,res.status,t); falhas.push({status:res.status,body:t,count:chunk.length}); }
          else okCount+=chunk.length;
        }catch(e){ console.error("DB saveBatch error:",e); falhas.push({error:e.message,count:chunk.length}); }
      })();
      // Registra cada id deste chunk na mesma fila usada por save(), para que uma edição
      // individual feita logo em seguida (ex: mudar o Serviço de uma linha recém-importada)
      // sempre espere esta gravação em lote terminar antes de aplicar sua própria mudança,
      // em vez de correr o risco do lote (mais lento) chegar depois e apagar a edição.
      chunk.forEach(({id})=>{ __saveQueues[table+"::"+id]=chunkPromise; });
      await chunkPromise;
    }
    if(falhas.length>0){
      const falhouCount=falhas.reduce((s,f)=>s+f.count,0);
      alert(`⚠️ Importação parcial em "${table}": ${okCount} de ${rows.length} linha(s) salvas no banco.\n${falhouCount} linha(s) falharam ao salvar — tente reimportar (ou repetir só essa parte) depois.`);
    }
    return {ok:falhas.length===0,okCount,failedCount:rows.length-okCount};
  },
  // Exclui varias linhas de uma vez (usado pra limpar uma importacao errada). Vai em lotes pra nao sobrecarregar.
  async deleteBatch(table, ids, chunkSize=100) {
    if(!ids||ids.length===0)return {ok:true,okCount:0};
    let okCount=0;
    for(let i=0;i<ids.length;i+=chunkSize){
      const chunk=ids.slice(i,i+chunkSize);
      const lista=chunk.map(id=>`"${String(id).replace(/"/g,'')}"`).join(",");
      try{
        const res=await fetch(`${SUPA_URL}/rest/v1/${table}?id=in.(${encodeURIComponent(lista)})`,{
          method:"DELETE",
          headers:{"apikey":SUPA_KEY,"Authorization":`Bearer ${SUPA_KEY}`}
        });
        if(res.ok)okCount+=chunk.length;
        else console.error("DB deleteBatch error:",table,res.status,await res.text());
      }catch(e){ console.error("DB deleteBatch error:",e); }
    }
    return {ok:okCount===ids.length,okCount};
  }
};



