  // ── SINCRONIZAÇÃO EM TEMPO REAL (Supabase Realtime via WebSocket) ──
  // Qualquer insert/update/delete feito por qualquer usuário aparece na hora, sem precisar recarregar.
  useEffect(()=>{
    const setters={
      relatorios:setReports, processos_mu:setProcessosMU, processos_af:setProcessosAF,
      execucao_mau_uso:setExecMauUso, sas_pecas:setSasPecas, comercial:setComercial,
      sas_manutencao:setSasManutencao, sas_vendas:setSasVendas, documentos_sas:setDocumentosSas,
      vale_tecnico_maquinas:setValeTecnico, ferias_colaboradores:setFerias, treinamentos_reunioes:setTreinamentos, banco_horas:setBancoHoras, entrega_tecnica:setEntregaTec, clientes_sas:setClientesSas, prospeccao:setProspeccao, ponto_diario:setPontoDiario, escala_diaria:setEscalaDiaria, servicos_fechados:setServicosFechados, dificuldades_tecnicos:setDificuldadesTec, fechamento_mensal_oficina:setFechamentoMensal,
      saida_entrada:setSaidaEntrada, requisicoes:setRequisicoes, carros:setCarros,
      operacoes:setOperacoes, pendencias_frota:setFrota, rupturas_alm:setRupturas,
      sas:setSas, uber_pedidos:setUberPedidos, financeiro:setFinanceiro, cotacoes_pecas:setCotacoesPecas, envio_pecas_fornecedor:setEnvioPecas, orcamento_pecas:setOrcamentoPecas, pendencias_portal:setPendenciasPortal, pendencias_checklist:setPendenciasChecklist,
    };
    const applyChange=(table,eventType,rec,oldRec)=>{
      const setter=setters[table]; if(!setter)return;
      const row=rec&&rec.data!==undefined?rec.data:rec;
      const id=rec&&rec.id!==undefined?rec.id:(row&&row.id);
      if(!id)return;
      if(eventType!=="DELETE"){
        const lastLocal=__recentLocalSaves[table+"::"+id];
        if(lastLocal&&(Date.now()-lastLocal)<RECENT_SAVE_WINDOW_MS) return; // protege edição recente contra eco de tempo real fora de ordem
      }
      setter(prev=>{
        const arr=Array.isArray(prev)?prev:[];
        if(eventType==="DELETE"){ const delId=(oldRec&&oldRec.id)||id; return arr.filter(x=>x.id!==delId); }
        const exists=arr.some(x=>x.id===id);
        const novo={...(row||{}),id};
        return exists?arr.map(x=>x.id===id?novo:x):[novo,...arr];
      });
    };
    let ws, hbTimer, reconnectTimer, alive=true, ref=1;
    const connect=()=>{
      try{
        ws=new WebSocket(`${SUPA_URL.replace("https://","wss://")}/realtime/v1/websocket?apikey=${SUPA_KEY}&vsn=1.0.0`);
      }catch(e){ return; }
      ws.onopen=()=>{
        ws.send(JSON.stringify({topic:"realtime:public",event:"phx_join",payload:{config:{postgres_changes:[{event:"*",schema:"public"}]}},ref:String(ref++)}));
        hbTimer=setInterval(()=>{ if(ws&&ws.readyState===1) ws.send(JSON.stringify({topic:"phoenix",event:"heartbeat",payload:{},ref:String(ref++)})); },25000);
      };
      ws.onmessage=(msg)=>{
        try{
          const m=JSON.parse(msg.data);
          if(m.event==="postgres_changes"&&m.payload&&m.payload.data){
            const d=m.payload.data;
            applyChange(d.table, d.type, d.record, d.old_record);
          }
        }catch(e){}
      };
      ws.onclose=()=>{ clearInterval(hbTimer); if(alive){ reconnectTimer=setTimeout(connect,4000); } };
      ws.onerror=()=>{ try{ws.close();}catch(e){} };
    };
    connect();
    return ()=>{ alive=false; clearInterval(hbTimer); clearTimeout(reconnectTimer); try{ws&&ws.close();}catch(e){} };
  },[]);

  // ── SALVAR AUTOMATICAMENTE ──
